import{_ as a,o as e,c as i,a2 as t}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"Environmental Variables","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/windows-installation/environmental-variables.md","filePath":"getting-started/windows-installation/environmental-variables.md"}'),n={name:"getting-started/windows-installation/environmental-variables.md"};function l(p,s,r,h,o,d){return e(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="environmental-variables" tabindex="-1">Environmental Variables <a class="header-anchor" href="#environmental-variables" aria-label="Permalink to &quot;Environmental Variables&quot;">​</a></h1><p>Tradeboard reads configuration from <code>.env</code> in the application directory. Create it from the <code>.sample.env</code> shipped with the same Tradeboard release:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Copy-Item</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> .sample.env .env</span></span></code></pre></div><p>Do not copy an old environment block from documentation or another server. The checked-out <code>.sample.env</code> is the authoritative list; the current application template contains 97 active keys and declares <code>ENV_CONFIG_VERSION = &#39;1.0.7&#39;</code>.</p><h2 id="required-setup" tabindex="-1">Required Setup <a class="header-anchor" href="#required-setup" aria-label="Permalink to &quot;Required Setup&quot;">​</a></h2><p>At minimum, review these groups before starting Tradeboard:</p><h3 id="broker-credentials" tabindex="-1">Broker Credentials <a class="header-anchor" href="#broker-credentials" aria-label="Permalink to &quot;Broker Credentials&quot;">​</a></h3><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">BROKER_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;YOUR_BROKER_API_KEY&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">BROKER_API_SECRET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;YOUR_BROKER_API_SECRET&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">BROKER_API_KEY_MARKET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;YOUR_XTS_MARKET_API_KEY_IF_REQUIRED&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">BROKER_API_SECRET_MARKET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;YOUR_XTS_MARKET_API_SECRET_IF_REQUIRED&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">REDIRECT_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;http://127.0.0.1:5000/&lt;broker&gt;/callback&#39;</span></span></code></pre></div><p>The market-data credentials are used only by the XTS-based brokers (<code>fivepaisaxts</code>, <code>compositedge</code>, <code>ibulls</code>, <code>iifl</code>, <code>jainamxts</code>, <code>rmoney</code>, <code>wisdom</code>), which need a separate market-data login. Replace <code>&lt;broker&gt;</code> in <code>REDIRECT_URL</code> with the active plugin&#39;s callback path and use the public HTTPS host for remote deployments.</p><h3 id="security-secrets" tabindex="-1">Security Secrets <a class="header-anchor" href="#security-secrets" aria-label="Permalink to &quot;Security Secrets&quot;">​</a></h3><p><code>.sample.env</code> ships these three keys as explicit placeholders:</p><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">APP_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;TRADEBOARD_PLACEHOLDER_APP_KEY_REGENERATE_BEFORE_USE&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">API_KEY_PEPPER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;TRADEBOARD_PLACEHOLDER_API_KEY_PEPPER_REGENERATE_BEFORE_USE&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">FERNET_SALT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;TRADEBOARD_PLACEHOLDER_FERNET_SALT_REGENERATE_BEFORE_USE&#39;</span></span></code></pre></div><p>On first run Tradeboard detects the placeholders, generates fresh values with <code>secrets.token_hex(32)</code>, writes them back to <code>.env</code>, and prints a one-time <code>[Tradeboard first-run setup]</code> message. The install scripts do the same. You normally never edit these three lines by hand.</p><p>Never reuse values copied from examples, documentation, another installation, or a public repository. And never change <code>API_KEY_PEPPER</code> or <code>FERNET_SALT</code> on an installation that already has users or broker logins: they feed the password hashing and the Fernet key derivation, so rotating them makes stored passwords and encrypted broker tokens unrecoverable. If you genuinely need to rotate the pepper, use <code>uv run python upgrade/rotate_pepper.py</code>, which re-encrypts as it goes.</p><h3 id="application-and-realtime-urls" tabindex="-1">Application and Realtime URLs <a class="header-anchor" href="#application-and-realtime-urls" aria-label="Permalink to &quot;Application and Realtime URLs&quot;">​</a></h3><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">HOST_SERVER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;http://127.0.0.1:5000&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">FLASK_HOST_IP</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;127.0.0.1&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">FLASK_PORT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;5000&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">WEBSOCKET_HOST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;127.0.0.1&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">WEBSOCKET_PORT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;8765&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">WEBSOCKET_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;ws://127.0.0.1:8765&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ZMQ_HOST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;127.0.0.1&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ZMQ_PORT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;5555&#39;</span></span></code></pre></div><p>For a public deployment, terminate TLS at the supported reverse proxy, set <code>HOST_SERVER</code> to the public <code>https://</code> URL, and expose the raw WebSocket proxy through the documented <code>/ws</code> route. Keep ZeroMQ on loopback; it is not an authenticated public protocol.</p><h3 id="database-paths" tabindex="-1">Database Paths <a class="header-anchor" href="#database-paths" aria-label="Permalink to &quot;Database Paths&quot;">​</a></h3><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">DATABASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;sqlite:///db/tradeboard.db&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">LATENCY_DATABASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;sqlite:///db/latency.db&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">LOGS_DATABASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;sqlite:///db/logs.db&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">HEALTH_DATABASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;sqlite:///db/health.db&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">SANDBOX_DATABASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;sqlite:///db/sandbox.db&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">HISTORIFY_DATABASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;db/historify.duckdb&#39;</span></span></code></pre></div><p>Historify is DuckDB rather than SQLite, so its value is a plain file path and not a SQLAlchemy URL. The key is spelled <code>HISTORIFY_DATABASE_URL</code> in <code>.sample.env</code>; keep it exactly as the template has it.</p><h2 id="broker-allowlist" tabindex="-1">Broker Allowlist <a class="header-anchor" href="#broker-allowlist" aria-label="Permalink to &quot;Broker Allowlist&quot;">​</a></h2><p><code>VALID_BROKERS</code> is a comma-separated list of enabled plugin keys. The release template contains all 36 installed plugins:</p><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">VALID_BROKERS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;fivepaisa,fivepaisaxts,aliceblue,angel,arrow,compositedge,dhan,dhan_sandbox,definedge,deltaexchange,firstock,flattrade,fyers,groww,hdfcsecurities,hdfcsky,ibulls,iifl,iiflcapital,indmoney,jainamxts,kotak,motilal,mstock,nubra,paytm,pocketful,rmoney,samco,shoonya,tradejini,tradesmart,upstox,wisdom,zebu,zerodha&#39;</span></span></code></pre></div><p>Broker presence does not guarantee every optional exchange, GTT, historical-data, or streaming capability. See <a href="./../../connect-brokers/brokers/README.html">Brokers</a>.</p><h2 id="updating-an-existing-installation" tabindex="-1">Updating an Existing Installation <a class="header-anchor" href="#updating-an-existing-installation" aria-label="Permalink to &quot;Updating an Existing Installation&quot;">​</a></h2><ol><li>Back up <code>.env</code> securely (<code>Copy-Item .env .env.backup</code>).</li><li>Compare its <code>ENV_CONFIG_VERSION</code> with the new <code>.sample.env</code>.</li><li>Add new keys and review changed defaults; do not overwrite working broker credentials or generated secrets.</li><li>Never run <code>Copy-Item .sample.env .env</code> over a working installation. It discards your broker credentials and replaces <code>API_KEY_PEPPER</code> and <code>FERNET_SALT</code>, which permanently invalidates every stored password hash and every encrypted broker token.</li><li>Restart Tradeboard and read startup validation errors before enabling automation.</li></ol><p>Do not commit <code>.env</code>, paste it into an issue, or include it in a screenshot. It contains broker credentials, application secrets, and deployment policy.</p>`,27)])])}const E=a(n,[["render",l]]);export{c as __pageData,E as default};
